// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.infrastructureimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport android.content.IntentFilterimport android.os.BatteryManager/** * NOUS — Android Battery Probe (Module 6 v4 — Step 6.7). * * Real Android implementation of [BatteryProbe] — uses * [BatteryManager] + sticky [Intent.ACTION_BATTERY_CHANGED] broadcast * to read the current battery level + charging state. * * ## Why this matters * * The [BatteryAdaptiveController] needs to know: *  - Current battery % (decides whether to enable power-saving vision *    mode — strategy v4 says < 15% disables Omni-SLM). *  - Whether the device is charging (decides whether to allow aggressive *    inference — charging devices have no thermal/battery constraints). * * ## How it works * * Android's `ACTION_BATTERY_CHANGED` is a **sticky broadcast** — registering * for it returns the last broadcast immediately (no waiting for the next * change). This is the canonical Android pattern for one-shot battery reads * without keeping a long-running receiver registered. * *  - For **battery %**: extracts `BatteryManager.EXTRA_LEVEL` + `EXTRA_SCALE` *    and computes `level / scale * 100`. *  - For **charging state**: extracts `BatteryManager.EXTRA_STATUS` and *    checks against `BATTERY_STATUS_CHARGING` + `BATTERY_STATUS_FULL`. * * ## Real Android APIs used * *  - [Context.registerReceiver] with [IntentFilter] for *    [Intent.ACTION_BATTERY_CHANGED] (sticky broadcast → returns last value) *  - [BatteryManager.EXTRA_LEVEL], [BatteryManager.EXTRA_SCALE], *    [BatteryManager.EXTRA_STATUS] * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Battery-Adaptive Controller</a> */class AndroidBatteryProbe(    private val context: Context,) : BatteryProbe {    /**     * Read the most recent battery-changed sticky broadcast.     *     * Returns null if the broadcast is unavailable (rare — Android always     * emits one shortly after boot).     */    private fun readBatteryStickyIntent(): Intent? {        return try {            // Note: Android 13+ (TIRAMISU) requires RECEIVER_NOT_EXPORTED flag            // for non-system broadcasts, but ACTION_BATTERY_CHANGED is a system            // sticky broadcast that's still allowed without the flag.            @Suppress("UnspecifiedRegisterReceiverFlag")            context.registerReceiver(null, IntentFilter(Intent.ACTION_BATTERY_CHANGED))        } catch (t: Throwable) {            Timber.tag(TAG).w("Failed to read battery sticky broadcast.", t)            null        }    }    override suspend fun getBatteryPercent(): Int {        val intent = readBatteryStickyIntent() ?: return 100        val level = intent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)        val scale = intent.getIntExtra(BatteryManager.EXTRA_SCALE, -1)        if (level < 0 || scale <= 0) return 100        return (level.toFloat() / scale.toFloat() * 100f).toInt().coerceIn(0, 100)    }    override suspend fun isCharging(): Boolean {        val intent = readBatteryStickyIntent() ?: return false        val status = intent.getIntExtra(BatteryManager.EXTRA_STATUS, -1)        return status == BatteryManager.BATTERY_STATUS_CHARGING ||            status == BatteryManager.BATTERY_STATUS_FULL    }    private companion object {        private const val TAG = "AndroidBatteryProbe"    }}
